from taf.ul.kpi_selector.operations.factory_prototype.classical_factory_prototype import OperationFactoryPrototype
from taf.ul.kpi_selector.operations.reset_cu.classical_reset_cu.reset_cu_prototype import ResetCu
from taf.ul.kpi_selector.operations.reset_cu.classical_reset_cu.reset_cu_22R1 import ResetCu22R1
from taf.ul.kpi_selector.operations.reset_cu.classical_reset_cu.reset_cu_22R2 import ResetCu22R2
from taf.ul.kpi_selector.operations.reset_cu.classical_reset_cu.reset_cu_22R3 import ResetCu22R3
from taf.ul.kpi_selector.operations.reset_cu.classical_reset_cu.reset_cu_23R1 import ResetCu23R1


class ResetCuFactory(OperationFactoryPrototype):
    def __init__(self):
        super(ResetCuFactory, self).__init__()

    def get_kpi(self):
        """
        Gets kpi for reset cu operation.
        :return: dictionary with timeout, requirement and operation description for reset cu
        :rtype: dict
        """
        if self.bts.stream < "SBTS22R1":
            return ResetCu(self.bts).get_kpi()

        elif self.bts.stream == "SBTS22R1":
            return ResetCu22R1(self.bts).get_kpi()

        elif self.bts.stream == "SBTS22R2":
            return ResetCu22R2(self.bts).get_kpi()

        elif self.bts.stream == "SBTS22R3" or self.bts.stream == "SBTS22R4":
            return ResetCu22R3(self.bts).get_kpi()

        elif self.bts.stream >= "SBTS23R1":
            return ResetCu23R1(self.bts).get_kpi()

    def bts_setter(self, bts):
        """
        Hands over Bts instance for given testline.
        :param bts: Bts instance
        :type bts: Bts instance from /taf/ul/kpi_selector/BTSs
        """
        self.bts = bts
